from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    """Input to this function is a string represented multiple groups for nested parentheses 
    separated by spaces. For each of the group, output the deepest level of nesting of parentheses."""

    def max_depth(s: str) -> int:
        """Calculate the maximum depth of nested parentheses in a string."""
        depth = 0
        max_depth = 0
        for char in s:
            if char == '(':
                depth += 1
                max_depth = max(max_depth, depth)
            elif char == ')':
                depth -= 1
        return max_depth

    # Check if the input string is empty
    if not paren_string.strip():
        return []

    return [max_depth(group) for group in paren_string.split() if group]

