def separate_paren_groups(paren_string: str) -> List[str]:
    """Separate groups of balanced parentheses in a string into a list of strings."""
    stack = []
    result = []
    current_group = ''

    for char in paren_string:
        if char == '(':
            stack.append(char)
            current_group += char
        elif char == ')':
            if stack:
                stack.pop()
                current_group += char
                if not stack:
                    result.append(current_group)
                    current_group = ''
        else:
            continue

    return result

