class Palindrome:
    def __init__(self, string: str):
        self.string = string

    def is_palindrome(self) -> bool:
        """ Test if given string is a palindrome """
        return self.string == self.string[::-1]

    def make_palindrome(self) -> str:
        """ Find the shortest palindrome that begins with a supplied string """
        if not self.string:
            return ''

        # Find the longest postfix of supplied string that is a palindrome
        for i in range(len(self.string), 0, -1):
            postfix = self.string[-i:]
            if self.is_palindrome(postfix):
                prefix = self.string[:-i]
                return self.string + prefix[::-1]

        # If no palindrome is found, return the original string
        return self.string

