    Args:
        numbers (str): A space-delimited string of numbers.

    Returns:
        str: The sorted string of numbers.

    >>> sort_numbers('three one five')
    'one three five'
    """
    # Define a dictionary to map number names to their integer values
    num_dict = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4,
        'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9
    }

    # Split the input string into a list of numbers
    num_list: List[Number] = []
    for num in numbers.split():
        num_list.append(Number(num_dict[num], num))

    # Implement Merge Sort to sort the list of numbers
    def merge_sort(lst: List[Number]) -> List[Number]:
        if len(lst) <= 1:
            return lst
        mid = len(lst) // 2
        left = merge_sort(lst[:mid])
        right = merge_sort(lst[mid:])
        return merge(left, right)

    def merge(left: List[Number], right: List[Number]) -> List[Number]:
        result = []
        while left and right:
            if left[0].value <= right[0].value:
                result.append(left.pop(0))
            else:
                result.append(right.pop(0))
        result.extend(left)
        result.extend(right)
        return result

    # Sort the list of numbers using Merge Sort
    num_list = merge_sort(num_list)

    # Join the sorted list of numbers into a string
    return ' '.join([num.name for num in num_list])

